import './DesktopSidebar.css';
import { useEffect, useState } from 'react';
import process from 'process';
import Search from '../components/Search';
import TrendingSection from '../components/TrendingsSection'
import SuggestedUsersSection from '../components/SuggestedUsersSection'
import JoinSection from '../components/JoinSection'
import { getAccessToken } from './lib/CheckAuth';

// Sidebar data used to be hardcoded (one fake user, four fake hashtags).
// Now (backlog #19, #20):
//   Trending  = posts with the most likes in the last 7 days (public API)
//   Suggested = 3 random users other than the signed-in one
// Both load only when someone is signed in, as the sections did before.
export default function DesktopSidebar(props) {
  const [trendings, setTrendings] = useState([]);
  const [users, setUsers] = useState([]);
  const signedIn = Boolean(props.user);

  useEffect(() => {
    if (!signedIn) return;
    let cancelled = false;

    const load = async () => {
      const base = process.env.REACT_APP_BACKEND_URL;
      try {
        const res = await fetch(`${base}/api/activities/trending`, { method: 'GET' });
        if (res.ok && !cancelled) {
          setTrendings(await res.json());
        }
      } catch (err) {
        console.log('trending failed', err);
      }
      try {
        const headers = { 'Accept': 'application/json' };
        const accessToken = await getAccessToken();
        if (accessToken) {
          headers['Authorization'] = `Bearer ${accessToken}`;
        }
        const res = await fetch(`${base}/api/users/suggested`, { method: 'GET', headers: headers });
        if (res.ok && !cancelled) {
          setUsers(await res.json());
        }
      } catch (err) {
        console.log('suggested users failed', err);
      }
    };

    load();
    return () => { cancelled = true; };
  }, [signedIn]);

  let trending;
  if (props.user) {
    trending = <TrendingSection trendings={trendings} />
  }

  let suggested;
  if (props.user && users.length > 0) {
    suggested = <SuggestedUsersSection users={users} />
  }
  let join;
  if (props.user) {
  } else {
    join = <JoinSection />
  }

  return (
    <section>
      <Search />
      {trending}
      {suggested}
      {join}
      <footer>
        <a href="#">About</a>
        <a href="#">Terms of Service</a>
        <a href="#">Privacy Policy</a>
      </footer>
    </section>
  );
}

import './TrendingsSection.css';
import TrendItem from '../components/TrendItem';

// "Most liked this week" (backlog #20). Cruddur has no hashtags, so the
// section lists the posts with the most likes in the last 7 days.
export default function TrendingsSection(props) {
  let items;
  if (props.trendings.length > 0) {
    items = props.trendings.map(trending => {
      return <TrendItem key={trending.uuid} trending={trending} />
    });
  } else {
    items = <div className='trendings-empty'>No likes yet this week.</div>;
  }

  return (
    <div className="trendings">
      <div className='trendings-title'>
        Most liked this week
      </div>
      {items}
    </div>
  );
}

import './TrendItem.css';
import { Link } from 'react-router-dom';

// One "most liked this week" entry. There is no single-post page yet, so the
// entry links to the author's profile.
export default function TrendItem(props) {
  const trending = props.trending;
  const likes = trending.week_likes;

  return (
    <Link className="trending" to={'/@' + trending.handle}>
      <span className="message">{trending.message}</span>
      <span className="count">{trending.display_name} · {likes} {likes === 1 ? 'like' : 'likes'} this week</span>
    </Link>
  );
}

